+﻿using Infrastructure.Logs;
+using Microsoft.CodeAnalysis.CSharp;
+using Microsoft.EntityFrameworkCore;
+using Npoi.Mapper;
+using NPOI.SS.Formula.Functions;
+using OpenAuth.App.Finance.Dto;
+using OpenAuth.App.Finance.Interfaces;
+using OpenAuth.App.Interface;
+using OpenAuth.App.Order.Request;
+using OpenAuth.App.WMS.SaleDeliver;
+using OpenAuth.App.WMS.SaleDeliver.Interface;
+using OpenAuth.Repository.Domain.Sap;
+using OpenAuth.Repository.Domain.Settlement;
+using OpenAuth.Repository.Domain.Wms;
+using OpenAuth.Repository.Interface;
+using System;
+using System.Collections.Generic;
+using System.Linq;
+using System.Linq.Dynamic.Core;
+using System.Text;
+using System.Threading.Tasks;
+using Z.BulkOperations;
+using System.Globalization;
+using Infrastructure.Extensions;
+
+namespace OpenAuth.App.Finance
+{
+    /// <summary>
+    /// 交货未运输
+    /// </summary>
+    public class UnTransportDailyNPercentProcessor : OnlyUnitWorkBaeApp, IPenaltyRuleProcessor
+    {
+        /// <summary>
+        /// 
+        /// </summary>
+        public UnTransportDailyNPercentProcessor(IUnitWork unitWork, IAuth auth) : base(unitWork, auth)
+        {
+        }
+
+        /// <summary>
+        /// 处理器代码
+        /// </summary>
+        public string HandlerCode => "HANDLER_UNTRANSPORT_NPERCENT";
+     
+        /// <summary>
+        /// 处理器实现
+        /// </summary>
+        /// <param name="matchedRules"></param>
+        /// <returns></returns>
+        /// <exception cref="NotImplementedException"></exception>
+        public async Task<(List<PenaltyEventData> NewEvents, List<ResolvedEventData> ResolvedEvents, List<CanceledEventData> CanceledEvents)> ProcessAsync(IEnumerable<PenaltyRuleDefinition> matchedRules)
+        {
+            var newEvents = new List<PenaltyEventData>();
+            // 这种简单处理器通常只对应一个规则
+            var rule = matchedRules.FirstOrDefault();
+            if (rule == null)
+            {
+                return (newEvents, new List<ResolvedEventData>(), new List<CanceledEventData>());
+            }
+
+            try
+            {
+                //规则配置下的天数期限
+                var dayNumLimit = rule.InterestGracePeriodDays.Value;
+                
+                //已经开始计算罚息的交货单
+                var hadPenaltyPlEvents = await UnitWork.Find<PenaltyEvent>(
+                    e => rule.Id == e.RuleDefinitionId
+                ).ToListAsync();
+                var plOrders = hadPenaltyPlEvents.Select(x=> $"PL-{x.TriggerDocEntry}").ToList();
+
+                // 计算截止日期：当前日期减去规则配置的天数
+                var deadlineDate = DateTime.Now.AddDays(-dayNumLimit);
+                var cuffOffDate = new DateTime(2024, 6, 1, 0, 0, 0, DateTimeKind.Local);
+                var dlnDocEntry2024CutOff = await UnitWork.Find<ODLN>(x => x.DocDate >= cuffOffDate).Select(x => x.DocEntry).ToListAsync();
+                //已经交货但是未关联运输单 ， 开始计息节点 ：n天后未运输走（关联运输单）；结束计息节点：运输走（关联运输单）；
+                var saleDelivers =  await UnitWork.Find<sale_deliver>(x => !plOrders.Contains(x.deliver_order) && x.deliver_order != null && x.deliver_order != ""
+                    && x.serial_number == null && x.create_time < deadlineDate && x.service_order == null).ToListAsync();
+                saleDelivers.ForEach(x => x.deliver_order_erp3 = x.deliver_order.Replace("PL-", ""));
+                
+                var dlnDocEntrys = saleDelivers.Select(x => int.Parse(x.deliver_order_erp3)).Where(x => dlnDocEntry2024CutOff.Contains(x)).ToList();
+
+                saleDelivers = saleDelivers.Where(x => dlnDocEntry2024CutOff.Contains(int.Parse(x.deliver_order_erp3))).ToList();
+                //成本价是其 未运输走的数量（即交货数量） * 成本价
+                // 分批查询，每批1000个
+                const int batchSize = 1000;
+                var plDocTotalStockValues = new Dictionary<int, decimal>();
+                var plDocRelOrdrValue = new Dictionary<int, int>();
+                var plDocDateDic = new Dictionary<int, DateTime>(); 
+                for (int i = 0; i < dlnDocEntrys.Count; i += batchSize)
+                {
+                    var batch = dlnDocEntrys.Skip(i).Take(batchSize).ToList();
+                    var batchData = await UnitWork.Find<DLN1>(x => batch.Contains(x.DocEntry.Value))
+                        .Select(x => new { DocEntry = x.DocEntry.Value, TotalStockValue = x.StockPrice.Value * x.Quantity.Value,x.BaseEntry })
+                        .ToListAsync();
+                    var batchData2 = await UnitWork.Find<ODLN>(x => batch.Contains(x.DocEntry.Value))
+                        .Select(x => new { DocEntry = x.DocEntry.Value, DocData = x.DocDate.Value}).ToListAsync();
+                    
+                    // 将 batchData2 中的日期数据填充到 plDocDateDic
+                    foreach (var item in batchData2)
+                    {
+                        plDocDateDic[item.DocEntry] = item.DocData;
+                    }
+
+                    foreach (var g in batchData.GroupBy(x => x.DocEntry))
+                    {
+                        plDocTotalStockValues[g.Key] = g.Sum(x => x.TotalStockValue);
+                        if (g.Any(x => x.BaseEntry.HasValue))
+                        {
+                            plDocRelOrdrValue[g.Key] = g.First(x => x.BaseEntry.HasValue && x.BaseEntry > 0).BaseEntry.Value;
+                        }
+                    }
+                }
+                saleDelivers.ForEach(x =>
+                {
+                    if (plDocRelOrdrValue.TryGetValue(int.Parse(x.deliver_order_erp3), out var ordrEntry))
+                    {
+                        x.sale_order_erp4 = ordrEntry.ToString();
+                    }
+
+                });
+                // 获取所有销售订单号(ERP4)
+                var seDocEntrys = saleDelivers.Select(x => int.Parse(x.sale_order_erp4)).Distinct().ToList();
+                //找到对应订单的业务员（分批查询）
+                var ordrSlps = new List<(int DocEntry, int SlpCode, string SlpName)>();
+                for (int i = 0; i < seDocEntrys.Count; i += batchSize)
+                {
+                    var batch = seDocEntrys.Skip(i).Take(batchSize).ToList();
+                    var batchSlps = await (from ordr in UnitWork.Find<ORDR>(null)
+                                           join oslp in UnitWork.Find<OSLP>(null) on ordr.SlpCode equals oslp.SlpCode
+                                           where batch.Contains(ordr.DocEntry)
+                                           select new { ordr.DocEntry,SlpCode= ordr.SlpCode.Value, oslp.SlpName }).ToListAsync();
+                    ordrSlps.AddRange(batchSlps.Select(x => (x.DocEntry, x.SlpCode, x.SlpName)));
+                }
+                // 创建订单号到业务员信息的映射
+                var orderToSlpMap = ordrSlps.ToDictionary(x => x.DocEntry, x => new { x.SlpCode, x.SlpName });
+
+                foreach (var saledeliver in saleDelivers)
+                {
+                    // 获取当前交货单对应的订单号(ERP4)
+                    var saleOrderErp4 = int.Parse(saledeliver.sale_order_erp4);
+                    // 获取对应的业务员信息
+                    var slpInfo = orderToSlpMap.TryGetValue(saleOrderErp4, out var info) ? info : null;
+                    // 获取成本价总和
+                    var deliverOrderErp3 = int.Parse(saledeliver.deliver_order_erp3);
+                    var plDocDate = plDocDateDic.TryGetValue(deliverOrderErp3, out var date) ? date : DateTime.Now;
+                    plDocTotalStockValues.TryGetValue(deliverOrderErp3, out var totalStockValue);
+                    if(totalStockValue != 0)
+                    {
+                        newEvents.Add(new PenaltyEventData
+                        {
+                            SEDocEntry  = saleOrderErp4,
+                            RuleDefinitionId = rule.Id,
+                            SlpCode = slpInfo?.SlpCode, // 业务员代码
+                            SlpName = slpInfo?.SlpName ?? "", // 业务员姓名
+                            TriggerDocType = "ODLN", // 凭证类型，这里需要确认是否正确
+                            TriggerDocEntry = deliverOrderErp3.ToString(), // 发货单ERP3号
+                            PenaltyBaseAmount = totalStockValue, // 成本价总和
+                            TriggerEventDate =  plDocDate, // 起算日为发货单创建时间
+                            PenaltyStartDate = plDocDate,
+                            PenaltyType = rule.PenaltyType
+                        });
+                    }
+                }
+
+                var activePenaltyEvents = hadPenaltyPlEvents.Where(x => x.EventStatus == "ACTIVE").ToList();
+                var activePlOrders = hadPenaltyPlEvents.Select(x => $"PL-{x.TriggerDocEntry}").ToList();
+                // 需要结案的活跃事件ID
+                var resolvedIds = new List<ResolvedEventData>();
+
+                if (activePlOrders.Any())
+                {
+                    // 查询这些PL交货单是否已关联运输单（serial_number有值）
+                    var transportedSds = await UnitWork.Find<sale_deliver>(
+                        x => activePlOrders.Contains(x.deliver_order) && !string.IsNullOrWhiteSpace(x.serial_number)
+                    ).Select(x => x.deliver_order).ToListAsync();
+
+                    if (transportedSds.Any())
+                    {
+                        // 去掉PL-前缀还原成TriggerDocEntry
+                        var transportedEntries = transportedSds.Select(pl => pl.Replace("PL-", "")).ToList();
+
+                        // 找到对应未结案的PenaltyEvent
+                        var toResolveEvents = activePenaltyEvents
+                            .Where(e => transportedEntries.Contains(e.TriggerDocEntry))
+                            .ToList();
+
+                        resolvedIds.AddRange(toResolveEvents.Select(e => new ResolvedEventData
+                        {
+                            EventId = (long)e.Id,
+                            ActualResolvedDate = DateTime.Now
+                        }));
+                    }
+                }
+
+                return (newEvents, resolvedIds, new List<CanceledEventData>());
+            }
+            catch (Exception ex) 
+            {
+                LogHelper.Error(ex,"未运输交货单N%处理器异常", nameof(UnTransportDailyNPercentProcessor), nameof(ProcessAsync));
+                return (newEvents, new List<ResolvedEventData>(), new List<CanceledEventData>());
+            }
+        }
+
+       
+    }
+}
